referenceSolutions.javascript:
export function isPalindromeNumber(n        )          {
  if (n < 0) return false; const digits = String(n); for (let i = 0, j = digits.length - 1; i < j; i++, j--) if (digits[i] !== digits[j]) return false; return true;
}

